// FILES is generated by tools/prepare_cloudflare.py from the checked Web export.
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const file = FILES[url.pathname];
    if (!file) return env.ASSETS.fetch(request);
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      return new Response('Method not allowed', { status: 405 });
    }
    const headers = {
      'Content-Type': file.type,
      'Content-Length': String(file.size),
      'Cache-Control': 'public, max-age=0, must-revalidate',
      'ETag': '"' + file.sha256 + '"',
    };
    const validators = (request.headers.get('If-None-Match') || '')
      .split(',').map(value => value.trim().replace(/^W\//, ''));
    if (validators.includes(headers.ETag) || validators.includes('*')) {
      return new Response(null, { status: 304, headers: { ETag: headers.ETag } });
    }
    if (request.method === 'HEAD') return new Response(null, { headers });
    // Native piping avoids running JavaScript for every network buffer. The
    // fixed length also makes a truncated transfer fail instead of looking complete.
    const { readable, writable } = typeof FixedLengthStream === 'function'
      ? new FixedLengthStream(file.size) : new TransformStream();
    const pipeline = (async () => {
      try {
        for (const path of file.parts) {
          const response = await env.ASSETS.fetch(new Request(new URL(path, url)));
          if (!response.ok || !response.body) throw new Error('Missing asset part');
          await response.body.pipeTo(writable, { preventClose: true });
        }
        await writable.close();
      } catch (error) {
        await writable.abort(error).catch(() => {});
        throw error;
      }
    })();
    if (ctx) ctx.waitUntil(pipeline);
    else void pipeline.catch(() => {});
    return new Response(readable, { headers });
  },
};
